[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>WellStream Platform — Integrated Energy Data Management</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --navy: #0D1B2A;
      --navy-light: #1B2838;
      --teal: #00B4D8;
      --teal-dark: #0077B6;
      --green: #6CC24A;
      --gray: #3C424B;
      --white: #ffffff;
      --light-gray: #E8EEF2;
      --text-muted: #8BA3C1;
    }
    html { scroll-behavior: smooth; }
    body { font-family: 'Inter', sans-serif; background: var(--navy); color: var(--white); line-height: 1.6; }
    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

    /* Header */
    .header { position: fixed; top: 0; left: 0; right: 0; z-index: 1000; background: rgba(13, 27, 42, 0.95); backdrop-filter: blur(12px); border-bottom: 1px solid rgba(255,255,255,0.08); }
    .header-inner { display: flex; align-items: center; justify-content: space-between; height: 72px; }
    .logo { font-size: 24px; font-weight: 800; letter-spacing: -0.5px; }
    .logo span { color: var(--teal); }
    .nav { display: flex; align-items: center; gap: 32px; }
    .nav-dropdown { position: relative; }
    .nav-dropdown-btn { display: flex; align-items: center; gap: 6px; font-size: 15px; font-weight: 500; color: var(--white); cursor: pointer; padding: 8px 0; background: none; border: none; }
    .nav-dropdown-btn:hover { color: var(--teal); }
    .nav-dropdown-btn i { font-size: 12px; transition: transform 0.2s; }
    .nav-dropdown-menu { position: absolute; top: 100%; left: 0; background: var(--navy-light); border: 1px solid rgba(255,255,255,0.1); border-radius: 8px; padding: 8px 0; min-width: 200px; opacity: 0; visibility: hidden; transform: translateY(8px); transition: all 0.2s; }
    .nav-dropdown:hover .nav-dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }
    .nav-dropdown-menu a { display: block; padding: 10px 20px; font-size: 14px; transition: background 0.15s; }
    .nav-dropdown-menu a:hover { background: rgba(0,180,216,0.1); color: var(--teal); }
    .nav-links { display: flex; gap: 24px; }
    .nav-links a { font-size: 15px; font-weight: 500; transition: color 0.15s; }
    .nav-links a:hover { color: var(--teal); }
    .btn-demo { background: var(--teal); color: var(--navy) !important; padding: 10px 20px; border-radius: 6px; font-weight: 600; transition: all 0.2s !important; }
    .btn-demo:hover { background: var(--green) !important; transform: translateY(-1px); }
    .mobile-toggle { display: none; background: none; border: none; color: var(--white); font-size: 24px; cursor: pointer; }

    /* Hero */
    .hero { padding: 160px 0 100px; background: linear-gradient(135deg, var(--navy) 0%, var(--navy-light) 100%); position: relative; overflow: hidden; }
    .hero::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background: radial-gradient(ellipse at 30% 20%, rgba(0,180,216,0.15) 0%, transparent 50%), radial-gradient(ellipse at 80% 80%, rgba(108,194,74,0.08) 0%, transparent 50%); }
    .hero-content { position: relative; z-index: 1; text-align: center; max-width: 900px; margin: 0 auto; }
    .hero-eyebrow { font-size: 13px; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--teal); margin-bottom: 20px; }
    .hero h1 { font-size: clamp(36px, 6vw, 64px); font-weight: 800; line-height: 1.1; letter-spacing: -1px; margin-bottom: 24px; }
    .hero p { font-size: 18px; color: var(--text-muted); max-width: 600px; margin: 0 auto 40px; }
    .hero-btns { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }
    .btn-primary { background: var(--teal); color: var(--navy); padding: 14px 28px; border-radius: 8px; font-weight: 600; font-size: 15px; transition: all 0.2s; display: inline-flex; align-items: center; gap: 8px; }
    .btn-primary:hover { background: var(--green); transform: translateY(-2px); }
    .btn-secondary { background: transparent; color: var(--white); padding: 14px 28px; border-radius: 8px; font-weight: 600; font-size: 15px; border: 1px solid rgba(255,255,255,0.2); transition: all 0.2s; }
    .btn-secondary:hover { border-color: var(--teal); color: var(--teal); }

    /* Featured Banner */
    .featured-banner { background: linear-gradient(90deg, var(--navy-light) 0%, #1E3A5F 100%); border-radius: 12px; padding: 40px 48px; margin: 60px auto; max-width: 900px; display: flex; align-items: center; justify-content: space-between; gap: 32px; border: 1px solid rgba(0,180,216,0.2); }
    .featured-label { font-size: 11px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; color: var(--green); margin-bottom: 8px; }
    .featured-name { font-size: 28px; font-weight: 700; margin-bottom: 4px; }
    .featured-tagline { color: var(--text-muted); font-size: 15px; }
    .btn-learn { background: var(--teal); color: var(--navy); padding: 12px 24px; border-radius: 6px; font-weight: 600; font-size: 14px; white-space: nowrap; transition: all 0.2s; }
    .btn-learn:hover { background: var(--green); }

    /* Use Cases */
    .use-cases { padding: 100px 0; }
    .section-label { font-size: 12px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; color: var(--teal); margin-bottom: 16px; }
    .section-title { font-size: clamp(28px, 4vw, 42px); font-weight: 700; margin-bottom: 16px; }
    .section-desc { color: var(--text-muted); max-width: 600px; margin-bottom: 48px; }
    .use-case-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 24px; }
    .use-case-card { background: var(--navy-light); border: 1px solid rgba(255,255,255,0.06); border-radius: 12px; padding: 32px; transition: all 0.25s; cursor: pointer; }
    .use-case-card:hover { border-color: var(--teal); transform: translateY(-4px); box-shadow: 0 20px 40px rgba(0,0,0,0.3); }
    .use-case-card h3 { font-size: 18px; font-weight: 600; margin-bottom: 10px; }
    .use-case-card p { font-size: 14px; color: var(--text-muted); line-height: 1.6; }
    .use-cases-footer { text-align: center; margin-top: 40px; }
    .btn-ghost { color: var(--teal); font-weight: 600; font-size: 14px; display: inline-flex; align-items: center; gap: 6px; transition: gap 0.2s; }
    .btn-ghost:hover { gap: 10px; }

    /* Industry Tabs */
    .industry-tabs-section { padding: 80px 0 100px; background: var(--navy-light); }
    .industry-tabs { display: flex; gap: 4px; background: rgba(0,0,0,0.3); border-radius: 8px; padding: 4px; max-width: 700px; margin: 0 auto 40px; overflow-x: auto; }
    .industry-tab { padding: 12px 20px; font-size: 14px; font-weight: 600; color: var(--text-muted); background: transparent; border: none; border-radius: 6px; cursor: pointer; transition: all 0.2s; white-space: nowrap; }
    .industry-tab.active { background: var(--teal); color: var(--navy); }
    .industry-tab:hover:not(.active) { color: var(--white); }
    .industry-content { display: none; }
    .industry-content.active { display: block; }
    .industry-content-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; }
    .industry-content h3 { font-size: 24px; font-weight: 700; margin-bottom: 16px; }
    .industry-content p { color: var(--text-muted); margin-bottom: 24px; }
    .industry-features { list-style: none; }
    .industry-features li { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; font-size: 14px; }
    .industry-features li::before { content: '→'; color: var(--teal); font-weight: 700; }
    .industry-visual { background: linear-gradient(135deg, rgba(0,180,216,0.1) 0%, rgba(108,194,74,0.05) 100%); border-radius: 12px; height: 280px; display: flex; align-items: center; justify-content: center; border: 1px solid rgba(0,180,216,0.2); }

    /* Platform Ecosystem Diagram */
    .ecosystem { padding: 100px 0; }
    .ecosystem-diagram { display: grid; grid-template-columns: 1fr auto 1fr auto 1fr; gap: 24px; align-items: center; max-width: 1000px; margin: 60px auto 0; }
    .ecosystem-pillar { background: var(--navy-light); border: 1px solid rgba(0,180,216,0.2); border-radius: 12px; padding: 32px; text-align: center; }
    .ecosystem-pillar h4 { font-size: 16px; font-weight: 700; margin-bottom: 8px; color: var(--teal); }
    .ecosystem-pillar p { font-size: 13px; color: var(--text-muted); }
    .ecosystem-arrow { color: var(--teal); font-size: 24px; }
    .ecosystem-center { text-align: center; }
    .ecosystem-logo { width: 80px; height: 80px; background: linear-gradient(135deg, var(--teal) 0%, var(--green) 100%); border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto 12px; font-weight: 800; font-size: 28px; }
    .ecosystem-center span { font-size: 12px; color: var(--text-muted); }

    /* Company Culture */
    .culture { padding: 100px 0; background: linear-gradient(180deg, var(--navy) 0%, var(--navy-light) 100%); }
    .culture-content { max-width: 800px; margin: 0 auto; text-align: center; }
    .culture h2 { font-size: clamp(32px, 5vw, 48px); font-weight: 800; margin-bottom: 24px; }
    .culture p { color: var(--text-muted); font-size: 17px; line-height: 1.8; margin-bottom: 32px; }

    /* Renewables CTA */
    .renewables { padding: 100px 0; background: linear-gradient(135deg, #0A1628 0%, var(--navy-light) 100%); }
    .renewables-card { background: linear-gradient(135deg, rgba(108,194,74,0.15) 0%, rgba(0,180,216,0.1) 100%); border: 1px solid rgba(108,194,74,0.3); border-radius: 16px; padding: 60px; max-width: 900px; margin: 0 auto; text-align: center; }
    .renewables h2 { font-size: clamp(28px, 4vw, 40px); font-weight: 700; margin-bottom: 20px; }
    .renewables p { color: var(--text-muted); font-size: 16px; max-width: 600px; margin: 0 auto 32px; }
    .btn-green { background: var(--green); color: var(--navy); padding: 14px 28px; border-radius: 8px; font-weight: 600; display: inline-flex; align-items: center; gap: 8px; transition: all 0.2s; }
    .btn-green:hover { background: #5aad34; transform: translateY(-2px); }

    /* Footer */
    .footer { background: #080F18; padding: 80px 0 40px; }
    .footer-grid { display: grid; grid-template-columns: 2fr repeat(3, 1fr); gap: 48px; margin-bottom: 60px; }
    .footer-brand { max-width: 300px; }
    .footer-brand .logo { font-size: 28px; margin-bottom: 16px; display: block; }
    .footer-brand p { font-size: 14px; color: var(--text-muted); line-height: 1.7; }
    .footer-col h4 { font-size: 13px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase; color: var(--text-muted); margin-bottom: 20px; }
    .footer-col a { display: block; font-size: 14px; margin-bottom: 12px; color: var(--white); transition: color 0.15s; }
    .footer-col a:hover { color: var(--teal); }
    .footer-bottom { border-top: 1px solid rgba(255,255,255,0.08); padding-top: 32px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px; }
    .footer-bottom p { font-size: 13px; color: var(--text-muted); }
    .footer-portals { display: flex; gap: 24px; }
    .footer-portals a { font-size: 13px; font-weight: 600; transition: color 0.15s; }
    .footer-portals a:hover { color: var(--teal); }

    /* Cookie Banner */
    .cookie-banner { position: fixed; bottom: 0; left: 0; right: 0; background: var(--navy-light); border-top: 1px solid rgba(255,255,255,0.1); padding: 20px 24px; z-index: 999; display: none; align-items: center; justify-content: space-between; gap: 24px; }
    .cookie-banner.show { display: flex; }
    .cookie-banner p { font-size: 14px; color: var(--text-muted); max-width: 600px; }
    .cookie-banner-actions { display: flex; gap: 12px; }
    .cookie-btn { padding: 10px 20px; border-radius: 6px; font-weight: 600; font-size: 14px; cursor: pointer; transition: all 0.2s; border: none; }
    .cookie-btn.decline { background: transparent; border: 1px solid rgba(255,255,255,0.2); color: var(--white); }
    .cookie-btn.decline:hover { border-color: rgba(255,255,255,0.4); }
    .cookie-btn.accept { background: var(--teal); color: var(--navy); }
    .cookie-btn.accept:hover { background: var(--green); }

    /* Mobile menu */
    .mobile-menu { display: none; position: fixed; top: 72px; left: 0; right: 0; bottom: 0; background: var(--navy); z-index: 999; padding: 24px; }
    .mobile-menu.open { display: block; }
    .mobile-menu a { display: block; font-size: 18px; padding: 16px 0; border-bottom: 1px solid rgba(255,255,255,0.1); }
    .mobile-menu .btn-demo { text-align: center; margin-top: 24px; }

    @media (max-width: 768px) {
      .nav, .nav-links { display: none; }
      .mobile-toggle { display: block; }
      .hero { padding: 120px 0 80px; }
      .hero h1 { font-size: 32px; }
      .featured-banner { flex-direction: column; text-align: center; padding: 32px 24px; }
      .ecosystem-diagram { grid-template-columns: 1fr; gap: 16px; }
      .ecosystem-arrow { transform: rotate(90deg); }
      .industry-content-inner { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .footer-brand { grid-column: 1 / -1; }
    }
  </style>
</head>
<body>
  <!-- Header -->
  <header class="header">
    <div class="container header-inner">
      <a href="index.html" class="logo">Well<span>Stream</span></a>
      <nav class="nav">
        <div class="nav-dropdown">
          <button class="nav-dropdown-btn">Platform <i class="ri-arrow-down-s-line"></i></button>
          <div class="nav-dropdown-menu">
            <a href="platform-overview.html">Platform Overview</a>
            <a href="security.html">Security</a>
            <a href="integration.html">Integration</a>
          </div>
        </div>
        <div class="nav-links">
          <a href="#">Solutions</a>
          <a href="#">Company</a>
        </div>
      </nav>
      <a href="request-demo.html" class="btn-demo">Request A Demo</a>
      <button class="mobile-toggle" onclick="toggleMobileMenu()"><i class="ri-menu-line"></i></button>
    </div>
  </header>

  <!-- Mobile Menu -->
  <div class="mobile-menu" id="mobileMenu">
    <a href="platform-overview.html">Platform Overview</a>
    <a href="security.html">Security</a>
    <a href="integration.html">Integration</a>
    <a href="#">Solutions</a>
    <a href="#">Company</a>
    <a href="request-demo.html" class="btn-demo">Request A Demo</a>
  </div>

  <!-- Hero -->
  <section class="hero">
    <div class="container hero-content">
      <p class="hero-eyebrow">Integrated Energy Data Platform</p>
      <h1>GET REAL-TIME DATA ACROSS YOUR ENTIRE OPERATION</h1>
      <p>The integrated energy data platform built for operators who demand speed, security, and visibility across the well data lifecycle.</p>
      <div class="hero-btns">
        <a href="platform-overview.html" class="btn-primary">Explore the Platform <i class="ri-arrow-right-line"></i></a>
        <a href="request-demo.html" class="btn-secondary">Request A Demo</a>
      </div>
    </div>
  </section>

  <!-- Featured Product Banner -->
  <div class="container">
    <div class="featured-banner">
      <div>
        <p class="featured-label">Featured Product</p>
        <h3 class="featured-name">WellStream Innova</h3>
        <p class="featured-tagline">Real-Time Drilling</p>
      </div>
      <a href="#" class="btn-learn">Learn More</a>
    </div>
  </div>

  <!-- Use Cases -->
  <section class="use-cases">
    <div class="container">
      <p class="section-label">USE CASES</p>
      <h2 class="section-title">See the WellStream Platform in Action</h2>
      <p class="section-desc">From drilling to production, land to water, watch how WellStream transforms every phase of your operations.</p>
      <div class="use-case-grid">
        <div class="use-case-card">
          <h3>Drilling & Completions Management</h3>
          <p>Centralize drilling programs, daily reports, and well design data in one accessible hub.</p>
        </div>
        <div class="use-case-card">
          <h3>Production Operations Oversight</h3>
          <p>Monitor production volumes, allocations, and decline curves with real-time dashboards.</p>
        </div>
        <div class="use-case-card">
          <h3>Asset Integrity Monitoring</h3>
          <p>Track well integrity risks, inspection schedules, and compliance status across your portfolio.</p>
        </div>
        <div class="use-case-card">
          <h3>Hydraulic Frac Data Centralization</h3>
          <p>Consolidate frac stage data, chemical usage, and pressure readings for every completion.</p>
        </div>
        <div class="use-case-card">
          <h3>Facility Construction & Commissioning</h3>
          <p>Manage site activity, construction milestones, and commissioning workflows digitally.</p>
        </div>
        <div class="use-case-card">
          <h3>Geospatial Asset Analysis</h3>
          <p>Visualize well locations, land positions, and infrastructure on interactive map layers.</p>
        </div>
      </div>
      <div class="use-cases-footer">
        <a href="#" class="btn-ghost">More Use Cases <i class="ri-arrow-right-line"></i></a>
      </div>
    </div>
  </section>

  <!-- Industry Tabs -->
  <section class="industry-tabs-section">
    <div class="container">
      <div class="industry-tabs" id="industryTabs">
        <button class="industry-tab active" data-tab="ep">E&P</button>
        <button class="industry-tab" data-tab="midstream">Midstream</button>
        <button class="industry-tab" data-tab="downstream">Downstream</button>
        <button class="industry-tab" data-tab="utilities">Utilities</button>
        <button class="industry-tab" data-tab="solarwind">Solar/Wind</button>
        <button class="industry-tab" data-tab="mining">Mining</button>
      </div>
      <div class="industry-content active" id="content-ep">
        <div class="industry-content-inner">
          <div>
            <h3>Exploration & Production Solutions</h3>
            <p>End-to-end well lifecycle management from exploration to production, with real-time data visibility across your entire operation.</p>
            <ul class="industry-features">
              <li>Centralized drilling and completions data</li>
              <li>Real-time production monitoring and allocation</li>
              <li>Well integrity and risk management</li>
              <li>Automated regulatory reporting</li>
            </ul>
          </div>
          <div class="industry-visual">
            <svg width="200" height="200" viewBox="0 0 200 200" fill="none">
              <circle cx="100" cy="100" r="80" stroke="#00B4D8" stroke-width="2" stroke-dasharray="8 4"/>
              <circle cx="100" cy="100" r="60" stroke="#6CC24A" stroke-width="2"/>
              <circle cx="100" cy="100" r="40" fill="rgba(0,180,216,0.2)"/>
              <circle cx="100" cy="100" r="20" fill="#00B4D8"/>
            </svg>
          </div>
        </div>
      </div>
      <div class="industry-content" id="content-midstream">
        <div class="industry-content-inner">
          <div>
            <h3>Midstream Operations</h3>
            <p>Optimize pipeline and transportation operations with integrated logistics and throughput visibility.</p>
            <ul class="industry-features">
              <li>Pipeline throughput monitoring</li>
              <li>Storage tank inventory management</li>
              <li>Batch scheduling and tracking</li>
              <li>SCADA integration capabilities</li>
            </ul>
          </div>
          <div class="industry-visual">
            <svg width="200" height="200" viewBox="0 0 200 200" fill="none">
              <path d="M20 100 L80 100 L100 60 L120 100 L180 100" stroke="#00B4D8" stroke-width="3" fill="none"/>
              <circle cx="80" cy="100" r="8" fill="#6CC24A"/>
              <circle cx="120" cy="100" r="8" fill="#6CC24A"/>
            </svg>
          </div>
        </div>
      </div>
      <div class="industry-content" id="content-downstream">
        <div class="industry-content-inner">
          <div>
            <h3>Downstream Processing</h3>
            <p>Streamline refinery and processing operations with integrated supply chain and inventory management.</p>
            <ul class="industry-features">
              <li>Refinery production tracking</li>
              <li>Inventory and logistics management</li>
              <li>Quality control and lab integration</li>
              <li>Distributor and retail analytics</li>
            </ul>
          </div>
          <div class="industry-visual">
            <svg width="200" height="200" viewBox="0 0 200 200" fill="none">
              <rect x="40" y="60" width="40" height="80" fill="rgba(0,180,216,0.3)" stroke="#00B4D8" stroke-width="2"/>
              <rect x="90" y="40" width="40" height="100" fill="rgba(0,180,216,0.3)" stroke="#00B4D8" stroke-width="2"/>
              <rect x="140" y="70" width="30" height="70" fill="rgba(108,194,74,0.3)" stroke="#6CC24A" stroke-width="2"/>
            </svg>
          </div>
        </div>
      </div>
      <div class="industry-content" id="content-utilities">
        <div class="industry-content-inner">
          <div>
            <h3>Utilities Management</h3>
            <p>Modernize utility operations with integrated asset management and smart grid integration.</p>
            <ul class="industry-features">
              <li>Grid infrastructure monitoring</li>
              <li>Demand forecasting and load management</li>
              <li>Asset performance tracking</li>
              <li>Regulatory compliance automation</li>
            </ul>
          </div>
