            <svg width="200" height="200" viewBox="0 0 200 200" fill="none">
              <path d="M100 20 L100 60 M80 40 L100 60 L120 40" stroke="#00B4D8" stroke-width="3"/>
              <circle cx="100" cy="120" r="40" stroke="#6CC24A" stroke-width="2"/>
              <path d="M70 120 L100 150 L130 120" stroke="#00B4D8" stroke-width="2"/>
            </svg>
          </div>
        </div>
      </div>
      <div class="industry-content" id="content-solarwind">
        <div class="industry-content-inner">
          <div>
            <h3>Solar & Wind Energy</h3>
            <p>Maximize renewable energy output with integrated monitoring and optimization capabilities.</p>
            <ul class="industry-features">
              <li>Solar array performance monitoring</li>
              <li>Wind farm output optimization</li>
              <li>Energy storage management</li>
              <li>Predictive maintenance analytics</li>
            </ul>
          </div>
          <div class="industry-visual">
            <svg width="200" height="200" viewBox="0 0 200 200" fill="none">
